fn polymulx(c: Vec<f32>) -> Vec<f32> {
    let n = c.len();
    let mut result = Vec::with_capacity(n + 1);
    // First element must be 0.0
    result.push(0.0);

    // Counter for how many elements have been copied so far
    let mut count = 0;

    // Loop invariant:
    // - count <= n
    // - result.len() == count + 1
    // - result[0] == 0.0
    // - For all 0 <= k < count: result[k+1] == c[k]

    while count < n {
        // Copy the element at index `count` from input to result at position count+1
        result.push(c[count]);
        count += 1; 
        // loop variant: n - count decreases strictly every iteration, guaranteeing termination
    }

    result
}